<?php $reference=['account'=>$message['account_id'],'folder'=>$message['folder'],'uid'=>$message['uid'],'validity'=>$message['uidvalidity']];?>
<div class="page-header"><div><h1><?=e($message['subject']?:'Zonder onderwerp')?></h1><p class="sub"><?=e($account['label'])?></p></div><a class="nav-link" href="<?=e(url('mail?'.http_build_query(['account'=>$message['account_id'],'folder'=>$message['folder']])))?>"><?=icon('arrowLeft')?>Mailbox</a></div>
<article class="card"><dl class="detail-list"><div><dt>Van</dt><dd><?=e($message['from'])?></dd></div><div><dt>Aan</dt><dd><?=e($message['to'])?></dd></div><div><dt>Datum</dt><dd><?=e($message['date'])?></dd></div></dl><div class="divider"></div><div class="mail-body"><?=e($message['body'])?></div><?php if($message['truncated']):?><p class="hint">Dit lange bericht is ingekort.</p><?php endif;?><?php if($message['attachments']):?><div class="divider"></div><h2>Bijlagen</h2><div class="actions"><?php foreach($message['attachments'] as $a):?><a class="btn btn-secondary btn-sm" href="<?=e(url('mail/message?'.http_build_query($reference+['part'=>$a['part']])))?>"><?=icon('link')?><?=e($a['filename'])?></a><?php endforeach;?></div><?php endif;?></article>
<div class="actions form-actions"><a class="btn btn-primary" href="<?=e(url('mail/compose?'.http_build_query(['account'=>$message['account_id'],'folder'=>$message['folder'],'reply'=>$message['uid'],'validity'=>$message['uidvalidity']])))?>"><?=icon('edit')?>Antwoorden</a></div>
<div class="card"><h2>Bericht beheren</h2><form method="post" action="<?=e(url('mail/message/mark'))?>" data-loading><?=csrf_field()?><?php foreach(['account_id','folder','uid','uidvalidity'] as $key):?><input type="hidden" name="<?=$key?>" value="<?=e((string)$message[$key])?>"><?php endforeach;?><div class="actions"><label class="checkbox-row"><input type="checkbox" name="read" value="1" <?=$message['seen']?'checked':''?>>Gelezen</label><label class="checkbox-row"><input type="checkbox" name="flagged" value="1" <?=$message['flagged']?'checked':''?>>Gemarkeerd</label><button class="btn btn-secondary" type="submit">Status opslaan</button></div></form><div class="divider"></div><form method="post" action="<?=e(url('mail/message/move'))?>" data-loading><?=csrf_field()?><?php foreach(['account_id','folder','uid','uidvalidity'] as $key):?><input type="hidden" name="<?=$key?>" value="<?=e((string)$message[$key])?>"><?php endforeach;?><div class="field"><label for="target">Verplaatsen naar</label><select id="target" name="target"><?php foreach($folders as $f):if($f['name']===$message['folder'])continue;?><option value="<?=e($f['name'])?>"><?=e($f['name'])?></option><?php endforeach;?></select></div><button class="btn btn-secondary" type="submit">Verplaatsen</button></form><div class="divider"></div><form method="post" action="<?=e(url('mail/message/delete'))?>" data-loading><?=csrf_field()?><?php foreach(['account_id','folder','uid','uidvalidity'] as $key):?><input type="hidden" name="<?=$key?>" value="<?=e((string)$message[$key])?>"><?php endforeach;?><label class="checkbox-row"><input type="checkbox" name="confirmed" value="1" required>Verplaats dit bericht naar de prullenbak</label><button class="btn btn-danger" type="submit"><?=icon('trash')?>Verwijderen</button></form></div>
